<?php $listUrl=$base.'/portal-demo.php?'.http_build_query(['status'=>$status,'page'=>$current]).'#mis-solicitudes'; ?>
<?php if(!$requestDetail): ?><header class="workspace-heading"><div><h1>Solicitud no disponible</h1><p>Solo puedes consultar las solicitudes de tu cuenta.</p></div><a class="site-button button-outline" href="<?= $e($listUrl) ?>">Volver a mis solicitudes</a></header><?php else:
    $row=$requestDetail;
    $stateHelp=['approved'=>'Tu demo fue aprobada. Accede al sistema con las credenciales que te haya entregado administración.','new'=>'Recibimos tu solicitud. Estamos pendientes de contactarte.','contacted'=>'Ya iniciamos el contacto para conocer tu negocio.','scheduled'=>'Tu demostración está coordinada. Revisa las respuestas del equipo.','closed'=>'El seguimiento de esta solicitud ha finalizado.','rejected'=>'Tu solicitud fue rechazada. Puedes consultar el motivo en Seguimiento.'];
    $seen=array_column($detailEvents,'status');$phases=commercialDemoPhases($row['status']);
    $tabUrl=$base.'/portal-demo.php?'.http_build_query(['request'=>(int)$row['id'],'status'=>$status,'page'=>$current]);
?>
<header class="workspace-heading"><div><a class="site-text-link request-back" href="<?= $e($listUrl) ?>">Mis solicitudes</a><h1>Solicitud #<?= (int)$row['id'] ?></h1><p>Demostración · <?= $e($plans[$row['plan_key']]['name']??'Asesoría para elegir un plan') ?></p></div><span class="lead-status status-<?= $e($row['status']) ?>"><?= $e($statuses[$row['status']]??$row['status']) ?></span></header>
<?php if($row['status']==='approved'): ?><div class="demo-access-action"><a class="site-button" href="<?= $base ?>/login.php" data-system-access>Acceder al sistema</a></div><?php endif; ?>
<article class="workspace-section request-detail" aria-label="Ficha de solicitud">
<ol class="request-phases" style="--request-phase-count: <?= count($phases) ?>" aria-label="Fases de la solicitud"><?php foreach($phases as $key=>$label): ?><li class="<?= $row['status']===$key?'phase-current':(in_array($key,$seen,true)?'phase-recorded':'') ?>" <?= $row['status']===$key?'aria-current="step"':'' ?>><span><?= kontaIcon(in_array($key,$seen,true)?'check':'closing') ?></span><strong><?= $e($label) ?></strong></li><?php endforeach; ?></ol>
<div class="request-detail-state"><strong>Estado actual</strong><p><?= $e($stateHelp[$row['status']]??'Consulta el seguimiento de tu solicitud.') ?></p></div>
<nav class="request-detail-tabs" aria-label="Secciones de la solicitud"><a href="<?= $e($tabUrl.'&tab=datos') ?>" data-request-tab="datos" <?= $detailTab==='datos'?'aria-current="page"':'' ?>><?= kontaIcon('closing') ?>Datos de la solicitud</a><a href="<?= $e($tabUrl.'&tab=seguimiento') ?>" data-request-tab="seguimiento" <?= $detailTab==='seguimiento'?'aria-current="page"':'' ?>><?= kontaIcon('contactos') ?>Seguimiento <span><?= count($detailEvents) ?></span></a></nav>
<section id="request-tab-datos" class="request-detail-panel" data-request-panel="datos" <?= $detailTab!=='datos'?'hidden':'' ?>><h2>Datos de la solicitud</h2><p class="request-detail-description">Información que enviaste al solicitar la demostración.</p><dl class="request-detail-fields"><div><dt>Nombre</dt><dd><?= $e($row['full_name']) ?></dd></div><div><dt>Empresa o nombre personal</dt><dd><?= $e($row['business_name']) ?></dd></div><div><dt>Correo electrónico</dt><dd><?= $e($row['email']) ?></dd></div><div><dt>Teléfono / WhatsApp</dt><dd><?= $e($row['phone']) ?></dd></div><div><dt>Tipo de negocio</dt><dd><?= $e($sectors[$row['sector']]??$row['sector']) ?></dd></div><div><dt>Ciudad</dt><dd><?= $e($row['city']?:'No indicada') ?></dd></div><div><dt>Empresas</dt><dd><?= $e($row['company_count']) ?></dd></div><div><dt>Usuarios</dt><dd><?= $e($row['user_count']) ?></dd></div><div><dt>Contacto preferido</dt><dd><?= $e(['email'=>'Correo electrónico','phone'=>'Llamada','whatsapp'=>'WhatsApp'][$row['contact_method']]??'') ?></dd></div><div><dt>Fecha de solicitud</dt><dd><?= $e($row['created_at']) ?></dd></div></dl><div class="request-detail-needs"><h3>Lo que necesitas resolver</h3><p><?= $e($row['requirements']?:'No se indicaron necesidades adicionales.') ?></p></div></section>
<section id="request-tab-seguimiento" class="request-detail-panel" data-request-panel="seguimiento" <?= $detailTab!=='seguimiento'?'hidden':'' ?>><h2>Seguimiento y respuestas</h2><p class="request-detail-description">Cambios de estado y respuestas del equipo Konta para esta solicitud.</p><ol class="portal-timeline"><?php foreach($detailEvents as $event): ?><li><span class="workspace-event-mark"><?= kontaIcon('check') ?></span><div class="workspace-event"><header><strong><?= $e($statuses[$event['status']]??$event['status']) ?></strong><time><?= $e($event['created_at']) ?></time></header><?php if($event['message']!==''): ?><p><?= $e($event['message']) ?></p><?php endif; ?><small>Equipo Konta</small></div></li><?php endforeach; ?></ol></section>
</article><?php endif; ?>
